local espCache = {}
local function makeEsp(m)
    local col = RARITY_COLOR[tostring(m:GetAttribute("Rarity"))] or Color3.fromRGB(0, 255, 128)
    local hl = Instance.new("Highlight")
    hl.FillColor = col; hl.OutlineColor = Color3.fromRGB(255, 255, 255); hl.FillTransparency = 0.6
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop; hl.Adornee = m; hl.Parent = m
    local bb = Instance.new("BillboardGui")
    bb.Size = UDim2.fromOffset(220, 44); bb.StudsOffset = Vector3.new(0, 3.5, 0); bb.AlwaysOnTop = true
    bb.Adornee = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart"); bb.Parent = m
    local tl = Instance.new("TextLabel")
    tl.Size = UDim2.fromScale(1, 1); tl.BackgroundTransparency = 1; tl.TextColor3 = col
    tl.TextStrokeTransparency = 0.3; tl.Font = Enum.Font.GothamBold; tl.TextSize = 13; tl.Parent = bb
    return { hl = hl, bb = bb, tl = tl }
end
local function espLabel(m)
    return eggName(m) .. "  [" .. tostring(m:GetAttribute("Rarity") or "?") .. "]\n" .. commas(eggKg(m)) .. " kg"
end
local function clearEsp(e) pcall(function() e.hl:Destroy() end); pcall(function() e.bb:Destroy() end) end
