                    if m:IsA("Model") and eggHost(m) and rarOk then
                        present[m] = true
                        local e = espCache[m]
                        if not e or not (e.hl and e.hl.Parent) then e = makeEsp(m); espCache[m] = e end
                        pcall(function() e.tl.Text = espLabel(m) end)
                    end
                end
            end
