FG:AddButton({ Text = "Envoyer", Func = function()
    local now = tick()
    if now - lastFeedback < FEEDBACK_COOLDOWN then
        pcall(function() fbStatus:SetText(string.format("Attendez %d secondes avant de renvoyer.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
        return
    end
    local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
    local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
    if msg == "" then pcall(function() fbStatus:SetText("Le message est vide.") end); return end
    if #msg > 500 then pcall(function() fbStatus:SetText("Trop long (500 caractères max).") end); return end
    local low = msg:lower()
    if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
        pcall(function() fbStatus:SetText("Les liens ne sont pas autorisés.") end); return
    end
    pcall(function() fbStatus:SetText("Envoi...") end)
    task.spawn(function()
        local sok, err = sendFeedback(ftype, msg)
        if sok then
            lastFeedback = tick()
            pcall(function() fbStatus:SetText("Envoyé. Merci !") end)
            pcall(function() Opt.FeedbackMsg:SetValue("") end)
            notify("Votre retour a été envoyé. Merci !")
        else
            pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Échec : " .. tostring(err))) end)
        end
    end)
end })
